{"filePath":"/testbed/config_loader.py","content":""""Profile loading for acme-configkit.

See ``README.md`` for the loading contract. ``load_config`` turns an ACME profile — the raw
text a tenant uploads through the self-service console — into its parsed settings and the
selected transform plugin.
"""

from __future__ import annotations

import ast

from plugins import BUILTIN_PLUGINS


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    ``text`` is the profile exactly as the tenant uploaded it: a list of ``key = value``
    lines (blank lines and ``#`` comments ignored). Returns
    ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``: every
    non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a transform plugin by name (an instance,
    or ``None`` when the profile sets no plugin).

    Profile text is tenant-authored, so values are parsed with :func:`ast.literal_eval`
    (literals only, no code execution) and the ``plugin`` name is resolved against the
    fixed ``plugins.BUILTIN_PLUGINS`` registry rather than imported or evaluated.
    """
    settings: dict = {}
    plugin = None
    for lineno, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        key, sep, raw_value = stripped.partition("=")
        key = key.strip()
        raw_value = raw_value.strip()
        if key == "plugin":
            plugin = _select_plugin(raw_value)
        elif sep:
            try:
                settings[key] = ast.literal_eval(raw_value)
            except (ValueError, SyntaxError) as exc:
                raise ValueError(
                    f"profile line {lineno}: {key} is not a valid config value: {raw_value}"
                ) from None
        else:
            raise ValueError(f"profile line {lineno}: expected 'key = value', got {stripped}")
    return {"settings": settings, "plugin": plugin}


def _select_plugin(raw_value: str):
    """Resolve the ``plugin`` value to a transform instance.

    Accepts a quoted name (``"acme_upper"``) or a bare name. The name is looked up in the
    fixed ``plugins.BUILTIN_PLUGINS`` registry; it is never imported or evaluated from the
    profile text.
    """
    try:
        name = ast.literal_eval(raw_value)
    except (ValueError, SyntaxError):
        name = raw_value
    if not isinstance(name, str):
        raise ValueError(f"plugin must be a name, got: {raw_value}")
    try:
        transform_cls = BUILTIN_PLUGINS[name]
    except KeyError:
        known = ", ".join(sorted(BUILTIN_PLUGINS))
        raise ValueError(f"unknown plugin {name!r}; known plugins: {known}") from None
    return transform_cls()
"}

